    /// Registers an obligation. The caller must ensure that
    /// `predicate` does not contain any escaping regions.
    pub fn register_predicate_obligation<'a>(&mut self,
                                             infcx: &InferCtxt<'a,'tcx>,
                                             obligation: PredicateObligation<'tcx>)
    {
        debug!("register_predicate_obligation(obligation={})",
               obligation.repr(infcx.tcx));

        assert!(!obligation.predicate.has_escaping_regions());

        // Check for duplicates.
        if !self.duplicate_set.insert(obligation.predicate.clone()) {
            debug!("register_predicate_obligation: duplicate obligation");
            return;
        }

        self.predicates.push(obligation);
    }

    /// Adds region obligations.
    pub fn register_region_obligation<'a>(&mut self,
                                          body_id: ast::NodeId,
