/// Returns the keys present in `a` but not in `b`
fn diff_left<'a>(a: impl Iterator<Item = &'a String>, b: &[String]) -> Vec<String> {
    a.filter(|k| !b.contains(k))
        .map(|k| k.clone())
        .collect()
}

